begin;
create extension if not exists pgtap with schema extensions;
set local search_path=pg_catalog,extensions;
select plan(8);
select is((select count(*)::integer from pg_catalog.pg_trigger t join pg_catalog.pg_class c on c.oid=t.tgrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname in ('cv','ai','legal','admin','audit') and t.tgdeferrable and not t.tgisinternal),1,'all application deferred custom triggers are inventoried');
select ok((select p.prosecdef and p.proowner='app_api_owner'::regrole and p.proconfig=array['search_path=""'] from pg_catalog.pg_proc p where p.oid='ai.validate_policy_graph()'::regprocedure),'deferred graph validation retains restricted owner and empty search_path at commit');
select ok((select tgdeferrable and tginitdeferred from pg_catalog.pg_trigger where tgrelid='ai.policy_versions'::regclass and tgname='complete_policy'),'graph check remains deferred to transaction completion');
select ok(not pg_catalog.has_function_privilege('anon','ai.validate_policy_graph()','execute'),'anonymous callers cannot invoke graph trigger directly');
select ok(not pg_catalog.has_function_privilege('authenticated','ai.validate_policy_graph()','execute'),'authenticated callers cannot invoke graph trigger directly');
select ok(not pg_catalog.has_function_privilege('service_role','ai.validate_policy_graph()','execute'),'service API cannot invoke graph trigger directly');
select ok(not pg_catalog.has_schema_privilege('authenticated','ai','usage') and not pg_catalog.has_table_privilege('authenticated','ai.routing_rules','select'),'deferred checks require no new API schema/table grants');
select ok(not pg_catalog.has_schema_privilege('app_api_owner','ai','create'),'temporary ownership-transfer CREATE grant is revoked');
select * from finish();
rollback;
